def solve(inp, verbose=False):
    h,w=len(inp),len(inp[0])
    cnt={}
    for r in range(h):
        for c in range(w):
            cnt[inp[r][c]]=cnt.get(inp[r][c],0)+1
    # most common = bg
    bg=max(cnt,key=cnt.get)
    others=[c for c,v in cnt.items() if c!=bg]
    # candidates for fill color: second most common; dot color: rare ones
    items=[(v,c) for c,v in sorted(cnt.items())]
    fill=items[1][1] if len(items)>1 else None
    dots=[c for c in others if c!=fill]
    out=[row[:] for row in inp]
    obj={(r,c) for r in range(h) for c in range(w) if inp[r][c] not in (bg,) }
    # nearest object per dot per line
    def nearest_in_line(r,c,dx,dy):
        best=None
        while True:
            r+=dx;c+=dy
            if not(0<=r<h and 0<=c<w) or inp[r][c]!=bg:
                break
            d=r*c
            p=(r,c)
            if best is None or abs(p[0]-c)*abs(p[1]-r)<abs(best[0]-c)*abs(best[1]-r):
                best=p
        return best if best and inp[best[0]][best[1]]!=bg else None
    for r in range(h):
        for c in range(w):
            if inp[r][c] in dots:
                for dx,dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                    if dx==0:
                        near=nearest_in_line(r,c,dx,dy)
                        nr,nc=r+dx,c
                        if near is None: continue
                        while 0<=nr<h and 0<=nc<w and inp[nr][nc]==bg:
                            out[nr][nc]=fill; nr+=dx; nc+=dy
                        out[r][c]=4
                    else:
                        near=nearest_in_line(r,c,dx,dy)
                        nr,nc=r,c+dy
                        if near is None: continue
                        while 0<=nr<h and 0<=nc<w and inp[nr][nc]==bg:
                            out[nr][nc]=fill; nr+=dx; nc+=dy
                        out[r][c]=4
    return out

