def f(g):
    g=[r[:] for r in g]
    h,w=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    # find stray dots: cells whose color != bg and count <= 3 and not part of a larger same-color component... use isolated cells
    cells_by_color={}
    for r in range(h):
        for c in range(w):
            v=g[r][c]
            cells_by_color.setdefault(v,[]).append((r,c))
    dots=[]
    for v,pos in cells_by_color.items():
        if v!=bg and len(pos)<=3:
            dots.extend(pos)
    # group strays into components (contiguous same color)
    comps=[]
    seen=set()
    for p in dots:
        if p in seen: continue
        stack=[p]; comp=[]
        while stack:
            r,c=stack.pop()
            if (r,c) in seen: continue
            seen.add((r,c)); comp.append((r,c))
            for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
                nr,nc=r+dr,c+dc
                if 0<=nr<h and 0<=nc<w and g[nr][nc]==v and (nr,nc) not in seen:
                    stack.append((nr,nc))
        comps.append(comp)
    dotcomps=[c for c in comps if len(c)==1]
    # fill color = dot color; dot becomes 4
    out=[r[:] for r in g]
    for comp in dotcomps:
        r,c,v=comp[0]
        out[r][c]=4
        # primary: toward nearest non-bg in the row, else nearest in the column, else nearest overall
        def dist(a,b): return abs(a[0]-b[0])+abs(a[1]-b[1])
        cand=[]
        for r2 in range(h):
            for c2 in range(w):
                if g[r2][c2]!=bg and (r2,c2)!=(r,c):
                    cand.append(((r2,c2),dist((r,c),(r2,c2))))
        best=min(cand,key=lambda x:x[1])
        (tr,tc),d=best
        if tr==r:
            dc=(tc-c)
            dr=0
        elif tc==c:
            dr=(tr-r); dc=0
        else:
            dr,dc=sign(tr-r),sign(tc-c)
        def sign(x): return 1 if x>0 else -1
        # actually choose direction toward target along the axis it differs; if both differ use row-priority
        if tr==r:
            dr,dc=0,sign(tc-c)
        elif tc==c:
            dr,dc=sign(tr-r),0
        else:
            dr,dc=sign(tr-r),sign(tc-c)
        rr,cc=r+dr,c+dc
        while 0<=rr<h and 0<=cc<w and g[rr][cc]==bg:
            out[rr][cc]=v; rr+=dr; cc+=dc
    return out

